from retry import should_retry

class TestShouldRetry(unittest.TestCase):
    def test_429_retry(self):
        """Status 429 should always retry"""
        self.assertTrue(should_retry(429, None))
        self.assertTrue(should_retry(429, "unknown"))

    def test_5xx_retry(self):
        """All 5xx errors should retry"""
        for status in [500, 501, 502, 503, 504, 505, 599]:
            self.assertTrue(should_retry(status, None))
            self.assertTrue(should_retry(status, "unknown"))

    def test_4xx_no_retry(self):
        """Other 4xx errors should not retry (except 429)"""
        for status in [400, 401, 403, 404, 405, 418]:
            self.assertFalse(should_retry(status, None))
            self.assertFalse(should_retry(status, "unknown"))

    def test_none_status_timeout_retry(self):
        """When status is None and error is timeout, should retry"""
        self.assertTrue(should_retry(None, "timeout"))

    def test_none_status_connection_retry(self):
        """When status is None and error is connection, should retry"""
        self.assertTrue(should_retry(None, "connection"))

    def test_none_status_other_error_no_retry(self):
        """When status is None and error is not timeout/connection, should not retry"""
        for error in ["unknown", "invalid", "auth", "not_found"]:
            self.assertFalse(should_retry(None, error))

    def test_unknown_error_false(self):
        """Unknown errors with status None must return false"""
        self.assertFalse(should_retry(None, "unknown"))
        self.assertFalse(should_retry(None, "invalid"))

    def test_401_no_retry(self):
        """Status 401 should not retry"""
        self.assertFalse(should_retry(401, None))
        self.assertFalse(should_retry(401, "unknown"))

if __name__ == "__main__":
    unittest.main()
